POS_EFFECT = "wh_main_effect_force_all_campaign_replenishment_rate"
POS_SCOPE = "faction_to_force_own"
# PER TIER, SO THE LADDER IS LINEAR AND SYMMETRIC: -6, -3, +3, +6. Deliberately smaller than
